import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import { splitProps } from 'solid-js';
import styles from './Kbd.module.css';

function Kbd(props: HTMLArkProps<'kbd'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.kbd
      {...others}
      data-scope="kbd"
      data-part="root"
      data-slot="kbd-root"
      class={clsx(styles.root, local.class)}
    />
  );
}

function KbdGroup(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      {...others}
      role="group"
      data-scope="kbd"
      data-part="group"
      data-slot="kbd-group"
      class={clsx(styles.group, local.class)}
    />
  );
}

export { Kbd, KbdGroup };

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: inline-flex;
    flex: none;
    min-width: var(--moduix-kbd-height, var(--moduix-size-xs));
    min-height: var(--moduix-kbd-height, var(--moduix-size-xs));
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-1);
    border: var(--moduix-kbd-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-kbd-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-kbd-radius, var(--moduix-radius-sm));
    padding-inline: var(--moduix-kbd-padding-x, var(--moduix-spacing-2));
    background-color: var(--moduix-kbd-bg, var(--moduix-color-muted));
    box-shadow: var(
      --moduix-kbd-shadow,
      inset 0 -1px 0 color-mix(in oklab, currentColor 12%, transparent)
    );
    color: var(--moduix-kbd-color, var(--moduix-color-foreground));
    font-family: var(--moduix-font-mono);
    font-size: var(--moduix-text-xs);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-xs);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    vertical-align: middle;
    user-select: none;

    & > :where(svg) {
      width: var(--moduix-spacing-3);
      height: var(--moduix-spacing-3);
      flex-shrink: 0;
      pointer-events: none;
    }
  }

  .group {
    display: inline-flex;
    max-width: 100%;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--moduix-spacing-1);
    color: var(--moduix-color-muted-foreground);
    vertical-align: middle;
  }
}
